import { Content } from "@prismicio/client";
import { SliceComponentProps } from "@prismicio/react";
import { PrismicNextLink, PrismicNextImage } from "@prismicio/next";
import { ReactNode } from "react";

export type HeaderNavigationProps = SliceComponentProps<Content.HeaderNavigationSlice>;

const HeaderNavigation = ({ slice }: HeaderNavigationProps): ReactNode => {
  return (
    <header
      data-slice-type={slice.slice_type}
      data-slice-variation={slice.variation}
      className="sticky top-0 z-50 bg-[#EBF7F8]/90 backdrop-blur-md border-b border-teal-100/50"
    >
      <div className="container mx-auto px-4 md:px-8 max-w-7xl flex items-center justify-between h-20">
        
        {/* Logo */}
        <div className="flex items-center gap-2">
          {slice.primary.logo ? (
            <PrismicNextImage
  field={slice.primary.logo}
  fallbackAlt=""
  className="h-10 w-auto object-contain"
  priority
/>
          ) : (
            <span className="text-2xl font-black text-[#0B2545]">
              Sym<span className="text-[#00A896]">Ventra</span>
            </span>
          )}
        </div>

        {/* Dynamic Navigation Links */}
        <nav className="hidden lg:flex items-center gap-8 text-sm font-medium text-slate-700">
          {slice.primary.nav_links?.map((item, index) => (
            <PrismicNextLink
              key={index}
              field={item.link}
              className="hover:text-[#00A896] transition-colors"
            >
              {item.label}
            </PrismicNextLink>
          ))}
        </nav>

        {/* CTA Button Link */}
        {slice.primary.cta_button && (
          <div className="flex items-center gap-4">
            <PrismicNextLink
              field={slice.primary.cta_button}
              className="rounded-full bg-[#00A896] px-6 py-2.5 text-sm font-semibold text-white hover:bg-[#028090] transition-colors shadow-sm"
            >
              {slice.primary.cta_button.text || "Join Pilot"}
            </PrismicNextLink>
          </div>
        )}

      </div>
    </header>
  );
};

export default HeaderNavigation;